using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed Discriminator property from documents
            // when only one entity type maps to a container. Existing documents still
            // have it, so we must explicitly preserve it for backward compatibility.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Breaking change 2: EF 9 changed id format from "EntityType|KeyValue"
            // to just "KeyValue". Existing documents use "Blog|1" format, so we must
            // preserve the old id factory to read/write them correctly.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: EF 9 Cosmos provider no longer supports HasIndex().
            // Indexes in Cosmos DB are managed via the indexing policy, not EF.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}

